# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">DENKLEŞTİRİLMİŞ TEPKİMEDE STOKİYOMETRİK KATSAYI YORUMU</text>\n  <rect x="22" y="40" width="656" height="38" rx="8" fill="#1e293b"/>\n  <text x="350" y="64" text-anchor="middle" font-size="15" font-weight="bold" fill="#f8fafc">N₂(g)   +   3H₂(g)   ⟶   2NH₃(g)    (H = 1 g/mol, N = 14 g/mol)</text>\n  <rect x="22" y="86" width="155" height="132" rx="8" fill="#eff6ff" stroke="#2563eb" stroke-width="1.8"/>\n  <text x="100" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. MOL SAYISI ORANI</text>\n  <text x="100" y="130" text-anchor="middle" font-size="11" fill="#1e3a8a">1 mol N₂ gazı</text>\n  <text x="100" y="150" text-anchor="middle" font-size="11" fill="#1e3a8a">+ 3 mol H₂ gazı</text>\n  <text x="100" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#1d4ed8">⟶ 2 mol NH₃ gazı</text>\n  <text x="100" y="198" text-anchor="middle" font-size="10" fill="#475569">(Mol korunmak zorunda değildir)</text>\n  <rect x="189" y="86" width="155" height="132" rx="8" fill="#f0fdf4" stroke="#16a34a" stroke-width="1.8"/>\n  <text x="266" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. TANECİK SAYISI</text>\n  <text x="266" y="130" text-anchor="middle" font-size="11" fill="#14532d">1·N_A tane N₂ molekülü</text>\n  <text x="266" y="150" text-anchor="middle" font-size="11" fill="#14532d">+ 3·N_A tane H₂ molekülü</text>\n  <text x="266" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#15803d">⟶ 2·N_A tane NH₃</text>\n  <text x="266" y="198" text-anchor="middle" font-size="10" fill="#475569">(Atom sayısı daima korunur!)</text>\n  <rect x="356" y="86" width="155" height="132" rx="8" fill="#fff7ed" stroke="#ea580c" stroke-width="1.8"/>\n  <text x="433" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">3. KÜTLE İLİŞKİSİ</text>\n  <text x="433" y="130" text-anchor="middle" font-size="11" fill="#7c2d12">28 g N₂ gazı</text>\n  <text x="433" y="150" text-anchor="middle" font-size="11" fill="#7c2d12">+ 3×2 = 6 g H₂ gazı</text>\n  <text x="433" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">⟶ 2×17 = 34 g NH₃</text>\n  <text x="433" y="198" text-anchor="middle" font-size="10" fill="#475569">(28 + 6 = 34 g Kütle korunur!)</text>\n  <rect x="523" y="86" width="155" height="132" rx="8" fill="#faf5ff" stroke="#9333ea" stroke-width="1.8"/>\n  <text x="600" y="106" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. GAZ HACMİ (NŞA)</text>\n  <text x="600" y="130" text-anchor="middle" font-size="11" fill="#581c87">22,4 L N₂(g) (1 hacim)</text>\n  <text x="600" y="150" text-anchor="middle" font-size="11" fill="#581c87">+ 67,2 L H₂(g) (3 hacim)</text>\n  <text x="600" y="170" text-anchor="middle" font-size="11" font-weight="bold" fill="#7e22ce">⟶ 44,8 L NH₃(g) (2 hacim)</text>\n  <text x="600" y="198" text-anchor="middle" font-size="10" fill="#475569">(Gaz katsayısı = Hacim oranı)</text>\n  <rect x="22" y="226" width="656" height="24" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="242" text-anchor="middle" font-size="11.2" font-weight="bold" fill="#1e293b">Stokiyometrik katsayılar (1 : 3 : 2) doğrudan MOL, MOLEKÜL ve (gazlar için) HACİM oranını verir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">STOKİYOMETRİK HESAPLAMA KÖPRÜSÜ (4 ADIMLI YÖNTEM)</text>\n  <rect x="22" y="48" width="148" height="125" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="96" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">1. ADIM: DENKLEM</text>\n  <text x="96" y="96" text-anchor="middle" font-size="10.5" fill="#1e3a8a">Tepkime denklemini</text>\n  <text x="96" y="114" text-anchor="middle" font-size="10.5" fill="#1e3a8a">yaz ve en küçük tam</text>\n  <text x="96" y="132" text-anchor="middle" font-size="10.5" fill="#1e3a8a">sayılarla denkleştir.</text>\n  <text x="96" y="156" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">aA + bB ⟶ cC</text>\n  <line x1="170" y1="110" x2="192" y2="110" stroke="#1e293b" stroke-width="2.5"/>\n  <rect x="192" y="48" width="148" height="125" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="266" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#166534">2. ADIM: MOLE ÇEVİR</text>\n  <text x="266" y="96" text-anchor="middle" font-size="10.5" fill="#14532d">Verilen niceliği</text>\n  <text x="266" y="114" text-anchor="middle" font-size="10.5" fill="#14532d">mol sayısına dönüştür:</text>\n  <text x="266" y="134" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">n = m / M_A</text>\n  <text x="266" y="150" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">n = N / N_A</text>\n  <text x="266" y="166" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">n = V / 22,4 (NŞA)</text>\n  <line x1="340" y1="110" x2="362" y2="110" stroke="#1e293b" stroke-width="2.5"/>\n  <rect x="362" y="48" width="148" height="125" rx="10" fill="#ffedd5" stroke="#ea580c" stroke-width="2"/>\n  <text x="436" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#9a3412">3. ADIM: KATSAYI GEÇİŞİ</text>\n  <text x="436" y="96" text-anchor="middle" font-size="10.5" fill="#7c2d12">Denklem katsayılarını</text>\n  <text x="436" y="114" text-anchor="middle" font-size="10.5" fill="#7c2d12">kullanarak istenen</text>\n  <text x="436" y="132" text-anchor="middle" font-size="10.5" fill="#7c2d12">maddenin molünü bul:</text>\n  <text x="436" y="156" text-anchor="middle" font-size="11" font-weight="bold" fill="#c2410c">n_A / a = n_C / c</text>\n  <line x1="510" y1="110" x2="532" y2="110" stroke="#1e293b" stroke-width="2.5"/>\n  <rect x="532" y="48" width="146" height="125" rx="10" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="605" y="72" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#6b21a8">4. ADIM: İSTENEN BİRİM</text>\n  <text x="605" y="96" text-anchor="middle" font-size="10.5" fill="#581c87">Bulunan mol sayısını</text>\n  <text x="605" y="114" text-anchor="middle" font-size="10.5" fill="#581c87">soruda istenen birime</text>\n  <text x="605" y="132" text-anchor="middle" font-size="10.5" fill="#581c87">dönüştür:</text>\n  <text x="605" y="152" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">m = n · M_A</text>\n  <text x="605" y="168" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7e22ce">V = n · 22,4 L</text>\n  <rect x="22" y="186" width="656" height="62" rx="8" fill="#fef2f2" stroke="#dc2626" stroke-width="1.5"/>\n  <text x="350" y="206" text-anchor="middle" font-size="12" font-weight="bold" fill="#991b1b">ÖRNEK UYGULAMA: CH₄(g) + 2O₂(g) ⟶ CO₂(g) + 2H₂O(s)   (CH₄ = 16 g/mol, CO₂ = 44 g/mol)</text>\n  <text x="350" y="226" text-anchor="middle" font-size="11" fill="#7f1d1d">8 gram CH₄ yakılırsa: n(CH₄) = 8 / 16 = 0,5 mol CH₄  ⟶  Katsayı (1:2) ile 1 mol O₂ harcanır (NŞA\'da 22,4 L)</text>\n  <text x="350" y="242" text-anchor="middle" font-size="11" fill="#7f1d1d">Katsayı (1:1) ile 0,5 mol CO₂ oluşur (0,5 × 44 = 22 g CO₂) ve katsayı (1:2) ile 1 mol H₂O (18 g su) oluşur.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SINIRLAYICI BİLEŞEN (ARTAN MADDE) VE TEPKİME VERİMİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">SINIRLAYICI BİLEŞEN (BİTEN MADDE)</text>\n  <text x="34" y="88" font-size="10.8" fill="#1e3a8a">• Tepkimede tamamen tükenerek tepkimenin</text>\n  <text x="42" y="104" font-size="10.8" fill="#1e3a8a">durmasına neden olan reaktife <tspan font-weight="bold">sınırlayıcı bileşen</tspan> denir.</text>\n  <text x="34" y="126" font-size="10.8" font-weight="bold" fill="#1d4ed8">• Oluşan ürün miktarı sınırlayıcı bileşene göre bulunur!</text>\n  <text x="34" y="148" font-size="10.5" fill="#1e3a8a">• Bulma kuralı: Her reaktif için <tspan font-weight="bold">(Başlangıç Molü / Katsayı)</tspan></text>\n  <text x="42" y="164" font-size="10.5" fill="#1e3a8a">oranı hesaplanır; bu oranı <tspan font-weight="bold">KÜÇÜK</tspan> olan sınırlayıcıdır.</text>\n  <text x="34" y="186" font-size="10.5" fill="#1e3a8a">• Tam verimli tepkimede girenlerden en az biri biter.</text>\n  <text x="34" y="206" font-size="10.5" fill="#1e3a8a">• Biten madde yoksa tepkime %100 verimli değildir.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">BAŞLANGIÇ - DEĞİŞİM - SONUÇ (BDS) TABLOSU</text>\n  <text x="370" y="90" font-size="11" font-weight="bold" fill="#14532d">Denklem:      N₂(g)  +  3H₂(g)  ⟶  2NH₃(g)</text>\n  <text x="370" y="114" font-size="10.8" fill="#14532d">Başlangıç:    2 mol     3 mol        —</text>\n  <text x="370" y="136" font-size="10.8" font-weight="bold" fill="#dc2626">Değişim:     -1 mol    -3 mol      +2 mol</text>\n  <line x1="370" y1="144" x2="660" y2="144" stroke="#166534" stroke-width="1.5"/>\n  <text x="370" y="162" font-size="10.8" font-weight="bold" fill="#15803d">Sonuç:        1 mol     0 (Bitti)    2 mol oluştu</text>\n  <text x="370" y="186" font-size="10.5" fill="#14532d">• Sınırlayıcı bileşen: H₂(g) | Artan madde: 1 mol N₂(g)</text>\n  <text x="370" y="206" text-anchor="middle" font-size="10.8" font-weight="bold" fill="#166534">% Verim = (Gerçek Ürün / Kuramsal Ürün) × 100</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Değişim (Harcanan/Oluşan) satırındaki mol sayıları daima tepkime denkleminin katsayılarıyla orantılıdır!</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
